// Begin bounded UUID helpers (candidate; not native evidence).
Процедура НаблюдатьUUID(Знач Метка, Знач Код)
    Попытка
        Результат = Неопределено;
        Выполнить(Код);
        Сообщить("uuid." + Метка + ": [" + Строка(Результат) + "]");
    Исключение
        Сообщить("uuid." + Метка + ": [error]");
    КонецПопытки;
КонецПроцедуры

Функция ФорматUUID(Знач Текст)
    Если СтрДлина(Текст) <> 36 Тогда Возврат Ложь; КонецЕсли;
    Для Позиция = 1 По 36 Цикл
        Знак = Сред(НРег(Текст), Позиция, 1);
        Если Позиция = 9 Или Позиция = 14 Или Позиция = 19 Или Позиция = 24 Тогда
            Если Знак <> "-" Тогда Возврат Ложь; КонецЕсли;
        Иначе
            Если Найти("0123456789abcdef", Знак) = 0 Тогда Возврат Ложь; КонецЕсли;
        КонецЕсли;
    КонецЦикла;
    Возврат Истина;
КонецФункции
Функция ПроекцияВходаUUID(Знач Значение)
    Текст = НРег(Строка(Значение));
    Возврат Строка(ТипЗнч(Значение)) + "/" + Строка(ФорматUUID(Текст))
        + "/" + Строка(Текст = "00000000-0000-0000-0000-000000000000")
        + "/" + Строка(Текст = "01234567-89ab-4cde-8f01-23456789abcd")
        + "/" + Сред(Текст, 15, 1);
КонецФункции

// End bounded UUID helpers.


// Begin bounded UUID codec helpers (candidate; not native evidence).
Функция ОграниченныйКодекUUID(Знач Текст)
    Если ТипЗнч(Текст) <> Тип("Строка") Тогда ВызватьИсключение "uuid-codec-type"; КонецЕсли;
    Если СтрДлина(Текст) > 256 Тогда ВызватьИсключение "uuid-codec-size"; КонецЕсли;
    Возврат Текст;
КонецФункции

Процедура НаблюдатьКодекUUID(Знач Метка, Знач Настройка, Знач Кодирование, Знач Декодирование)
    Значение = Неопределено;
    Текст = Неопределено;
    Результат = Неопределено;
    Попытка
        Выполнить(Настройка);
    Исключение
        Сообщить("uuid.codec." + Метка + ": [setup-error]");
        Возврат;
    КонецПопытки;
    Попытка
        Выполнить(Кодирование);
        Текст = ОграниченныйКодекUUID(Текст);
    Исключение
        Сообщить("uuid.codec." + Метка + ": [encode-error]");
        Возврат;
    КонецПопытки;
    Попытка
        Выполнить(Декодирование);
        Результат = ОграниченныйКодекUUID(Результат);
    Исключение
        Сообщить("uuid.codec." + Метка + ": [decode-error]");
        Возврат;
    КонецПопытки;
    Сообщить("uuid.codec." + Метка + ": [" + Результат + "]");
КонецПроцедуры
